pub fn RtlSecureZeroMemory(arg_ptr: PVOID, arg_cnt: SIZE_T) callconv(.c) PVOID {
    var ptr = arg_ptr;
    _ = &ptr;
    var cnt = arg_cnt;
    _ = &cnt;
    var vptr: [*c]volatile u8 = @ptrCast(@alignCast(ptr));
    _ = &vptr;
    while (cnt != 0) {
        (blk: {
            const ref = &vptr;
            const tmp = ref.*;
            ref.* += 1;
            break :blk tmp;
        }).* = 0;
        cnt -%= 1;
    }
    return ptr;
}
