    var hwnd = arg_hwnd;
    _ = &hwnd;
    var dwMask = arg_dwMask;
    _ = &dwMask;
    var dwAttributes = arg_dwAttributes;
    _ = &dwAttributes;
    var wta: WTA_OPTIONS = WTA_OPTIONS{
        .dwFlags = dwAttributes,
        .dwMask = dwMask,
    };
    _ = &wta;
